from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from post_office.models import Email, STATUS

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def retry_failed_email(request, email_id: int):
    try:
        # Enforce that the email was dispatched within the user's organization scope
        email = Email.objects.get(pk=email_id, headers__tenant_id=str(request.user.organization_id))
    except Email.DoesNotExist:
        return Response({'error': 'Email not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

    if not request.user.has_perm('mail.can_manage_deliveries'):
        return Response({'error': 'Insufficient permissions to re-queue deliveries'}, status=status.HTTP_403_FORBIDDEN)

    email.status = STATUS.queued
    email.save()
    return Response({'status': 'requeued', 'email_id': email.id, 'to': email.to})
